import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মানদণ্ড","description":"","frontmatter":{},"headers":[],"relativePath":"bn/17-位面至高强者标准.md","filePath":"bn/17-位面至高强者标准.md"}'),r={name:"bn/17-位面至高强者标准.md"};function e(h,t,n,d,u,s){return l(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-মানদণ্ড" tabindex="-1">ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মানদণ্ড <a class="header-anchor" href="#ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-মানদণ্ড" aria-label="Permalink to &quot;ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মানদণ্ড&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>17</td></tr><tr><td>মডিউল</td><td>মহাবিশ্বের আইন এবং সাধনা পদ্ধতি</td></tr><tr><td>মূল কীওয়ার্ড</td><td>ফেস-স্তরের সর্বোচ্চ, শক্তিশালীদের মানদণ্ড, 20% সক্রিয়করণ, বেন-ইয়ান জিং, শক্তিশালীদের দায়িত্ব</td></tr></tbody></table><h2 id="i-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-সংজ্ঞা-এবং-অবস্থান" tabindex="-1">I. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের সংজ্ঞা এবং অবস্থান <a class="header-anchor" href="#i-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-সংজ্ঞা-এবং-অবস্থান" aria-label="Permalink to &quot;I. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের সংজ্ঞা এবং অবস্থান&quot;">​</a></h2><p>&quot;ফেস-স্তরের সর্বোচ্চ শক্তিশালী&quot; হলো অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশন দ্বারা কসমিক স্তরের শক্তির স্তরে পৌঁছানো সাধকদের আনুষ্ঠানিক উপাধি, এবং এর অর্থ হলো সেইসব শীর্ষস্থানীয় সাধক যাদের ক্ষমতা স্বাধীনভাবে একটি ফেসের আইনের স্থিতিশীলতা বজায় রাখতে যথেষ্ট এবং যারা কসমিক স্কেলে প্রভাব ফেলতে সক্ষম। ঐক্যকৃত স্তর বিভাজনের মানদণ্ডে, ফেস-স্তরের সর্বোচ্চ শক্তিশালী নবম স্তর &quot;বেন-ইয়ান জিং&quot; এবং তার উপরের সাথে মেলে, এবং তারা হেঙ্গ-ইউয়ান জুতে সবচেয়ে শীর্ষস্থানীয় শক্তির গোষ্ঠী।</p><p>ফেস-স্তরের সর্বোচ্চ শক্তিশালী কেবল একটি শক্তির স্তরের উপাধি নয়, বরং এটি একটি দায়িত্ব এবং পরিচয়ের অবস্থানও। সিম্বায়োটিক সিভিলাইজেশনের কাঠামোর অধীনে, শক্তি যত বেশি হবে, দায়িত্ব তত বেশি হবে। ফেস-স্তরের সর্বোচ্চ শক্তিশালী কেবল ব্যক্তিগত সাধনার সফল ব্যক্তি নন, বরং তারা সিভিলাইজেশনের রক্ষক, আইনের রক্ষক, এবং পিছিয়ে থাকাদের পথপ্রদর্শক। সিম্বায়োটিক সিভিলাইজেশনের &quot;20% সক্রিয়করণ কৌশল&quot;, এর মূল লক্ষ্য হলো সিভিলাইজেশন প্রতিষ্ঠার প্রাথমিক পর্যায়ে, সকল প্রাণীর মোট সংখ্যার 20% ব্যক্তিকে ফেস-স্তরের সর্বোচ্চ শক্তিশালীর স্তরে সক্রিয় করা, এবং মহাবিশ্বের সামগ্রিক উন্নয়নের জন্য শক্তির ভিত্তি প্রতিষ্ঠা করা।</p><p>বিশেষভাবে বলা প্রয়োজন যে, সিম্বায়োটিক সিভিলাইজেশনের &quot;ফেস-স্তরের সর্বোচ্চ শক্তিশালী&quot; এবং লুটবাদ যুগের &quot;ফেস-স্তরের আধিপত্য&quot; এর মধ্যে মৌলিক পার্থক্য রয়েছে। লুটবাদ যুগের ফেস-স্তরের আধিপত্য শক্তি দিয়ে ফেসকে দাসত্বে পরিণত করত এবং সম্পদ লুট করত, এবং তারা ফেসের শাসক এবং লুটেরা ছিল; আর সিম্বায়োটিক সিভিলাইজেশনের ফেস-স্তরের সর্বোচ্চ শক্তিশালী শক্তি দিয়ে ফেসকে রক্ষা করে এবং সকল প্রাণীর সেবা করে, এবং তারা ফেসের রক্ষক এবং সেবাকারী। এই পার্থক্য হলো সিম্বায়োটিক সিভিলাইজেশনের লুটবিরোধী মূল ধারণার শক্তিশালীদের স্তরে সরাসরি প্রকাশ।</p><h2 id="ii-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-মূল্যায়নের-মানদণ্ড" tabindex="-1">II. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মূল্যায়নের মানদণ্ড <a class="header-anchor" href="#ii-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-মূল্যায়নের-মানদণ্ড" aria-label="Permalink to &quot;II. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মূল্যায়নের মানদণ্ড&quot;">​</a></h2><p>ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মূল্যায়ন &quot;চার-মাত্রিক মূল্যায়ন পদ্ধতি&quot; ব্যবহার করে, এবং চারটি মাত্রা সবগুলো মানদণ্ড পূরণ করলেই আনুষ্ঠানিকভাবে ফেস-স্তরের সর্বোচ্চ শক্তিশালী হিসেবে স্বীকৃতি দেওয়া হয়:</p><table tabindex="0"><thead><tr><th>মাত্রা</th><th>মূল্যায়নের বিষয়বস্তু</th><th>মানদণ্ড পূরণের মানদণ্ড</th><th>ওজন</th></tr></thead><tbody><tr><td>শক্তির মাত্রা</td><td>স্তর, শক্তির স্তর, আইন নিয়ন্ত্রণের ক্ষমতা</td><td>ঐক্যকৃত স্তরের নবম স্তর (বেন-ইয়ান জিং) এ পৌঁছানো, স্বাধীনভাবে মূল শক্তি সংগ্রহ করতে সক্ষম হওয়া</td><td>40%</td></tr><tr><td>চরিত্রের মাত্রা</td><td>মানসিক পরিপক্কতা, নৈতিক অঙ্গীকার, লুটবিরোধী অবস্থান</td><td>অ্যাঙ্কর আদালতের নৈতিক পরীক্ষা পাস করা, লুটবিরোধী নীতি এবং সিম্বায়োসিস ধারণার অঙ্গীকার নিশ্চিত করা</td><td>25%</td></tr><tr><td>অবদানের মাত্রা</td><td>সিম্বায়োটিক নেটওয়ার্ক, সিভিলাইজেশনের উন্নয়ন, এবং সকল জাতির অগ্রগতিতে অবদান</td><td>অবদানের মান সিভিলাইজেশনের শীর্ষ 20% স্তরে পৌঁছানো, কমপক্ষে একটি সিভিলাইজেশন-স্তরের অবদানের রেকর্ড থাকা</td><td>20%</td></tr><tr><td>দায়িত্বের মাত্রা</td><td>পাবলিক দায়িত্ব গ্রহণের ইচ্ছা এবং ক্ষমতা</td><td>ফেস-স্তরের বা তার উপরের পাবলিক দায়িত্ব (যেমন অ্যাঙ্কর রক্ষণাবেক্ষণ, সিভিলাইজেশন রক্ষা ইত্যাদি) গ্রহণ করতে ইচ্ছুক এবং সক্ষম হওয়া</td><td>15%</td></tr></tbody></table><p>চার-মাত্রিক মূল্যায়ন পদ্ধতির নকশা সিম্বায়োটিক সিভিলাইজেশনের &quot;গুণ ও কর্মদক্ষতা উভয়, গুণকে অগ্রাধিকার&quot; শক্তিশালীদের মূল্যায়নের ধারণাকে প্রকাশ করে। শক্তি কেবল ভিত্তি, চরিত্র, অবদান, এবং দায়িত্বও একইভাবে অপরিহার্য মানদণ্ড। একজন শক্তিশালী কিন্তু চরিত্র দুষ্ট এবং দায়িত্ব গ্রহণে অস্বীকারকারী সাধক, এমনকি যদি সে বেন-ইয়ান জিংয়ের শক্তির স্তরে পৌঁছায়, তবুও তাকে &quot;ফেস-স্তরের সর্বোচ্চ শক্তিশালী&quot; হিসেবে স্বীকৃতি দেওয়া হবে না, বরং তাকে &quot;উচ্চ-ঝুঁকির ব্যক্তি&quot; হিসেবে শ্রেণীবদ্ধ করা হবে এবং সংশ্লিষ্ট নিয়ন্ত্রণ ও সীমাবদ্ধতার অধীনে রাখা হবে।</p><h2 id="iii-শক্তির-মাত্রার-বিস্তারিত-মানদণ্ড" tabindex="-1">III. শক্তির মাত্রার বিস্তারিত মানদণ্ড <a class="header-anchor" href="#iii-শক্তির-মাত্রার-বিস্তারিত-মানদণ্ড" aria-label="Permalink to &quot;III. শক্তির মাত্রার বিস্তারিত মানদণ্ড&quot;">​</a></h2><p>শক্তির মাত্রা হলো ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মূল্যায়নের ভিত্তি, এবং এর বিস্তারিত মানদণ্ড অন্তর্ভুক্ত:</p><h3 id="_3-1-স্তরের-মানদণ্ড" tabindex="-1">3.1 স্তরের মানদণ্ড <a class="header-anchor" href="#_3-1-স্তরের-মানদণ্ড" aria-label="Permalink to &quot;3.1 স্তরের মানদণ্ড&quot;">​</a></h3><ul><li>অবশ্যই ঐক্যকৃত স্তরের নবম স্তর &quot;বেন-ইয়ান জিং&quot; এ পৌঁছাতে হবে, এবং মহাবিশ্বের মূল আইনকে স্পর্শ করতে হবে</li><li>স্থিরভাবে মূল শক্তি সংগ্রহ করতে সক্ষম হতে হবে, মাঝে মাঝে বিস্ফোরণমূলক সংগ্রহ নয়</li><li>ব্যক্তিগত পথ এবং মহাবিশ্বের মূল আইন গভীরভাবে মিশ্রিত, &quot;পথই মূল, মূলই পথ&quot; অবস্থায় পৌঁছাতে হবে</li></ul><h3 id="_3-2-শক্তির-মানদণ্ড" tabindex="-1">3.2 শক্তির মানদণ্ড <a class="header-anchor" href="#_3-2-শক্তির-মানদণ্ড" aria-label="Permalink to &quot;3.2 শক্তির মানদণ্ড&quot;">​</a></h3><ul><li>শরীরে সঞ্চিত মূল শক্তি &quot;ফেস-স্তর&quot; এ পৌঁছায় — অর্থাৎ মোট শক্তি একটি মাঝারি ফেসের মৌলিক আইন কার্যকলাপকে সমর্থন করার জন্য যথেষ্ট</li><li>শক্তির বিশুদ্ধতা 99% এর উপরে, প্রায় কোনো অমেধ্য নেই</li><li>শক্তি পুনরুদ্ধারের গতি &quot;তাৎক্ষণিক পুনরুদ্ধার&quot; এ পৌঁছায় — এমনকি যুদ্ধে ব্যাপক পরিমাণে ব্যবহারের পরেও, অত্যন্ত স্বল্প সময়ের মধ্যে পূর্ণ অবস্থায় ফিরে আসতে সক্ষম</li></ul><h3 id="_3-3-আইন-নিয়ন্ত্রণের-মানদণ্ড" tabindex="-1">3.3 আইন নিয়ন্ত্রণের মানদণ্ড <a class="header-anchor" href="#_3-3-আইন-নিয়ন্ত্রণের-মানদণ্ড" aria-label="Permalink to &quot;3.3 আইন নিয়ন্ত্রণের মানদণ্ড&quot;">​</a></h3><ul><li>কসমিক স্কেলে আইনের শক্তি সংগ্রহ এবং নিয়ন্ত্রণ করতে সক্ষম</li><li>মহাবিশ্বের আইনের সূক্ষ্ম সমন্বয় এবং অপ্টিমাইজেশনে অংশ নিতে সক্ষম, এবং আইনের কার্যকলাপে বাস্তব প্রভাব ফেলতে সক্ষম</li><li>অ্যাঙ্কর সহায়তা ছাড়াই স্বাধীনভাবে ক্রস-ফেস ভ্রমণ এবং অপারেশন করতে সক্ষম</li><li>বিচ্ছিন্ন স্থানে সম্পূর্ণ বিশ্ব এবং আইন সিস্টেম তৈরি করতে সক্ষম (সৃষ্টি-স্তরের ক্ষমতা)</li></ul><h3 id="_3-4-জীবনের-রূপের-মানদণ্ড" tabindex="-1">3.4 জীবনের রূপের মানদণ্ড <a class="header-anchor" href="#_3-4-জীবনের-রূপের-মানদণ্ড" aria-label="Permalink to &quot;3.4 জীবনের রূপের মানদণ্ড&quot;">​</a></h3><ul><li>জীবনের রূপ উচ্চ-মাত্রিক বিবর্তন সম্পন্ন করেছে, এবং একই সাথে পদার্থিক ফেস, শক্তি স্তর, এবং চেতনা অঞ্চলে বিদ্যমান এবং কার্যকলাপ করতে সক্ষম</li><li>অমরত্বের কাছাকাছি — স্বাভাবিক আক্রমণ এবং ক্ষতি তার জন্য মারাত্মক হুমকি সৃষ্টি করতে পারে না, এবং শুধুমাত্র সমান বা উচ্চতর স্তরের শক্তি তাকে প্রকৃতপক্ষে আঘাত করতে পারে</li><li>নিজের জীবনের ছাপকে মহাবিশ্বের মূলতে অ্যাঙ্কর করতে সক্ষম, এমনকি দেহ ধ্বংস হলেও মূল অ্যাঙ্করিংয়ের মাধ্যমে পুনর্জন্ম করতে সক্ষম</li></ul><h2 id="iv-চরিত্রের-মাত্রার-বিস্তারিত-মানদণ্ড" tabindex="-1">IV. চরিত্রের মাত্রার বিস্তারিত মানদণ্ড <a class="header-anchor" href="#iv-চরিত্রের-মাত্রার-বিস্তারিত-মানদণ্ড" aria-label="Permalink to &quot;IV. চরিত্রের মাত্রার বিস্তারিত মানদণ্ড&quot;">​</a></h2><p>চরিত্রের মাত্রা হলো সিম্বায়োটিক সিভিলাইজেশনের শক্তিশালীদের মূল্যায়নে সবচেয়ে বৈশিষ্ট্যপূর্ণ অংশ, এবং এটি লুটবাদ যুগের সাথে সবচেয়ে মৌলিক পার্থক্যও:</p><h3 id="_4-1-লুটবিরোধী-অবস্থান" tabindex="-1">4.1 লুটবিরোধী অবস্থান <a class="header-anchor" href="#_4-1-লুটবিরোধী-অবস্থান" aria-label="Permalink to &quot;4.1 লুটবিরোধী অবস্থান&quot;">​</a></h3><ul><li>মৌলিকভাবে লুটবাদকে সমর্থন এবং অনুশীলন করে, এবং কখনো লুটবাদী সাধনার রেকর্ড ছিল না</li><li>এমনকি চরম দুর্দশায়ও অন্যদের লুট করার বিনিময়ে আত্মরক্ষার পথ বেছে নেবে না</li><li>সকল রকমের লুটবাদী আচরণকে সক্রিয়ভাবে প্রতিরোধ এবং বিরোধ করে, এবং লুটবাদী শক্তির বিরুদ্ধে বলতে সাহসী</li></ul><h3 id="_4-2-সিম্বায়োসিস-ধারণা" tabindex="-1">4.2 সিম্বায়োসিস ধারণা <a class="header-anchor" href="#_4-2-সিম্বায়োসিস-ধারণা" aria-label="Permalink to &quot;4.2 সিম্বায়োসিস ধারণা&quot;">​</a></h3><ul><li>&quot;সকল জাতির সিম্বায়োসিস, মহাবিশ্বের উন্নয়ন&quot; সিভিলাইজেশনের মূল ধারণাকে গভীরভাবে বোঝে এবং সমর্থন করে</li><li>ব্যক্তিগত সাধনা এবং পাবলিক বিষয়ে সবসময় সিম্বায়োসিসের স্বার্থকে অগ্রাধিকার দেয়</li><li>সিম্বায়োটিক নেটওয়ার্কের নির্মাণ এবং রক্ষণাবেক্ষণে সক্রিয়ভাবে অংশ নেয়, এবং নিজের সাধনার ফলাফল এবং জ্ঞানকে সকল প্রাণীর সাথে শেয়ার করতে ইচ্ছুক</li></ul><h3 id="_4-3-মানসিক-পরিপক্কতা" tabindex="-1">4.3 মানসিক পরিপক্কতা <a class="header-anchor" href="#_4-3-মানসিক-পরিপক্কতা" aria-label="Permalink to &quot;4.3 মানসিক পরিপক্কতা&quot;">​</a></h3><ul><li>আবেগ স্থিতিশীল, এবং ব্যক্তিগত আবেগের কারণে সিভিলাইজেশন এবং সকল প্রাণীর ক্ষতি করে এমন আচরণ করে না</li><li>বিশাল মহাবিশ্বের দৃষ্টিভঙ্গি এবং দীর্ঘমেয়াদী ঐতিহাসিক দৃষ্টিভঙ্গি রয়েছে, এবং স্বল্পমেয়াদী স্বার্থের জন্য দীর্ঘমেয়াদী উন্নয়নকে বলিদান করে না</li><li>বিশাল চাপ এবং বিপত্তি সহ্য করতে সক্ষম, এবং দুর্দশায় যুক্তিবাদী এবং দৃঢ় থাকে</li></ul><h3 id="_4-4-নৈতিক-পরীক্ষা" tabindex="-1">4.4 নৈতিক পরীক্ষা <a class="header-anchor" href="#_4-4-নৈতিক-পরীক্ষা" aria-label="Permalink to &quot;4.4 নৈতিক পরীক্ষা&quot;">​</a></h3><p>চরিত্রের মাত্রার মূল্যায়ন অ্যাঙ্কর আদালতের অধীনস্থ &quot;নৈতিক পরীক্ষা কমিটি&quot; দ্বারা সঞ্চালিত হয়, এবং পরীক্ষার পদ্ধতি অন্তর্ভুক্ত:</p><ul><li>ঐতিহাসিক আচরণ পরীক্ষা: সাধকের চিরকালের সব গুরুত্বপূর্ণ আচরণের রেকর্ড পরীক্ষা করা</li><li>চেতনার গভীর স্ক্যান: সাধকের স্বেচ্ছায় চেতনা স্তরের গভীর স্ক্যান করা, এবং তার অন্তরের প্রকৃত চিন্তা নিশ্চিত করা</li><li>পরিস্থিতিগত চাপ পরীক্ষা: সিমুলেটেড পরিবেশে চরম নৈতিক দুর্দশা সেট করা, এবং সাধকের পছন্দ পর্যবেক্ষণ করা</li><li>দীর্ঘমেয়াদী পর্যবেক্ষণ: বিতর্কিত প্রার্থীদের জন্য, কয়েক বছরের দীর্ঘমেয়াদী পর্যবেক্ষণ এবং মূল্যায়ন করা</li></ul><h2 id="v-অবদানের-মাত্রার-বিস্তারিত-মানদণ্ড" tabindex="-1">V. অবদানের মাত্রার বিস্তারিত মানদণ্ড <a class="header-anchor" href="#v-অবদানের-মাত্রার-বিস্তারিত-মানদণ্ড" aria-label="Permalink to &quot;V. অবদানের মাত্রার বিস্তারিত মানদণ্ড&quot;">​</a></h2><p>অবদানের মাত্রা সিম্বায়োটিক সিভিলাইজেশন এবং সকল জাতির অগ্রগতিতে সাধকের প্রকৃত অবদানকে মাপে:</p><h3 id="_5-1-অবদানের-প্রকার" tabindex="-1">5.1 অবদানের প্রকার <a class="header-anchor" href="#_5-1-অবদানের-প্রকার" aria-label="Permalink to &quot;5.1 অবদানের প্রকার&quot;">​</a></h3><ul><li><strong>সাধনা অবদান</strong>: স্তর অতিক্রমের ডেমো প্রভাব, নতুন সাধনা পদ্ধতির সৃষ্টি, সাধনা তত্ত্বের উদ্ভাবন</li><li><strong>জ্ঞান অবদান</strong>: সাধনার অভিজ্ঞতার প্রকাশ্য শেয়ার, শিক্ষা ও প্রশিক্ষণ কাজ, একাডেমিক গবেষণার ফলাফল</li><li><strong>প্রযুক্তি অবদান</strong>: আইন প্রকৌশল প্রযুক্তির উদ্ভাবন, দ্বিগুণ ফল প্রযুক্তির অপ্টিমাইজেশন, অ্যাঙ্কর হার্ডওয়্যারের উন্নতি</li><li><strong>সেবা অবদান</strong>: অ্যাঙ্কর রক্ষণাবেক্ষণ, সিভিলাইজেশন শাসন, শিক্ষক নির্দেশনা, ক্রস-জাতি সমন্বয়</li><li><strong>পরিবেশ অবদান</strong>: গ্রহের পরিবেশ পুনরুদ্ধার, ফেস শক্তি চক্রের উন্নতি, মহাবিশ্বের পরিবেশ সুরক্ষা</li><li><strong>রক্ষা অবদান</strong>: বাহ্যিক হুমকি প্রতিরোধ, সিভিলাইজেশনের নিরাপত্তা রক্ষা, বিপর্যয়ে আক্রান্ত প্রাণীদের উদ্ধার</li></ul><h3 id="_5-2-অবদানের-পরিমাণ" tabindex="-1">5.2 অবদানের পরিমাণ <a class="header-anchor" href="#_5-2-অবদানের-পরিমাণ" aria-label="Permalink to &quot;5.2 অবদানের পরিমাণ&quot;">​</a></h3><p>অবদানের মান অ্যাঙ্কর নেটওয়ার্ক দ্বারা স্বয়ংক্রিয়ভাবে রেকর্ড এবং গণনা করা হয়, এবং বিভিন্ন প্রকারের অবদানকে তাদের প্রভাব এবং মূল্য অনুযায়ী বিভিন্ন ওজন দেওয়া হয়। ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের অবদানের মানদণ্ড হলো &quot;অবদানের মান সিভিলাইজেশনের শীর্ষ 20% স্তরে পৌঁছানো&quot;, এবং কমপক্ষে একটি &quot;সিভিলাইজেশন-স্তরের অবদান&quot; থাকা প্রয়োজন — অর্থাৎ সেই অবদান যা পুরো সিভিলাইজেশনের উন্নয়নে বড় এবং গভীর প্রভাব ফেলেছে।</p><h2 id="vi-দায়িত্বের-মাত্রার-বিস্তারিত-মানদণ্ড" tabindex="-1">VI. দায়িত্বের মাত্রার বিস্তারিত মানদণ্ড <a class="header-anchor" href="#vi-দায়িত্বের-মাত্রার-বিস্তারিত-মানদণ্ড" aria-label="Permalink to &quot;VI. দায়িত্বের মাত্রার বিস্তারিত মানদণ্ড&quot;">​</a></h2><p>দায়িত্বের মাত্রা সাধকের পাবলিক দায়িত্ব গ্রহণের ইচ্ছা এবং ক্ষমতাকে মাপে:</p><h3 id="_6-1-দায়িত্বের-প্রকার" tabindex="-1">6.1 দায়িত্বের প্রকার <a class="header-anchor" href="#_6-1-দায়িত্বের-প্রকার" aria-label="Permalink to &quot;6.1 দায়িত্বের প্রকার&quot;">​</a></h3><p>ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের গ্রহণ করতে হবে এমন পাবলিক দায়িত্ব অন্তর্ভুক্ত:</p><ul><li><strong>অ্যাঙ্কর রক্ষা</strong>: এক বা একাধিক উচ্চ-স্তরের অ্যাঙ্করের রক্ষা এবং রক্ষণাবেক্ষণের জন্য দায়ী</li><li><strong>সিভিলাইজেশন উপদেষ্টা</strong>: সিভিলাইজেশনের সর্বোচ্চ স্তরের উপদেষ্টা হিসেবে, সিভিলাইজেশনের উন্নয়নের দিকের সিদ্ধান্তে অংশ নেওয়া</li><li><strong>শিক্ষক উত্তরাধিকার</strong>: পরবর্তী প্রজন্মের সাধকদের প্রশিক্ষণ এবং নির্দেশনা দেওয়া, বিশেষ করে যারা সর্বোচ্চ স্তরে পৌঁছানোর সম্ভাবনা রয়েছে এমন বীজ খেলোয়াড়দের</li><li><strong>ফেস পরিদর্শন</strong>: নিয়মিতভাবে প্রতিটি ফেস পরিদর্শন করা, ফেসের স্থিতিশীলতা এবং সিভিলাইজেশনের উন্নয়নের অবস্থা পর্যবেক্ষণ করা</li><li><strong>সংকট মোকাবেলা</strong>: সিভিলাইজেশন বড় সংকটের মুখোমুখি হলে (যেমন ফেস ধ্বংস, বাহ্যিক আক্রমণ ইত্যাদি), সবচেয়ে মূল মোকাবেলার কাজ গ্রহণ করা</li><li><strong>আইন অংশগ্রহণ</strong>: মহাবিশ্বের আইনের সূক্ষ্ম সমন্বয় এবং অপ্টিমাইজেশনে অংশ নেওয়া, এবং মহাবিশ্বের সামগ্রিক উন্নয়নে শক্তি অবদান রাখা</li></ul><h3 id="_6-2-দায়িত্ব-গ্রহণের-পদ্ধতি" tabindex="-1">6.2 দায়িত্ব গ্রহণের পদ্ধতি <a class="header-anchor" href="#_6-2-দায়িত্ব-গ্রহণের-পদ্ধতি" aria-label="Permalink to &quot;6.2 দায়িত্ব গ্রহণের পদ্ধতি&quot;">​</a></h3><p>ফেস-স্তরের সর্বোচ্চ শক্তিশালী নিজের আগ্রহ এবং দক্ষতা অনুযায়ী, মূলভাবে গ্রহণ করা দায়িত্বের প্রকার বেছে নিতে পারে, কিন্তু সম্পূর্ণরূপে পাবলিক দায়িত্ব গ্রহণে অস্বীকার করতে পারবে না। সিম্বায়োটিক সিভিলাইজেশন &quot;শক্তিশালীদের বাধ্যবাধকতা পদ্ধতি&quot; প্রয়োগ করে — ফেস-স্তরের সর্বোচ্চ শক্তিশালীর স্তরে পৌঁছানো সাধকদের, তাদের শক্তির একটি অংশ পাবলিক বিষয়ে ব্যবহার করার বাধ্যবাধকতা রয়েছে। নির্দিষ্ট বাধ্যবাধকতার সময়কাল হলো প্রতি বছর কমপক্ষে 30% সময় এবং শক্তি পাবলিক দায়িত্বে বিনিয়োগ করা।</p><h2 id="vii-20-সক্রিয়করণ-কৌশল" tabindex="-1">VII. 20% সক্রিয়করণ কৌশল <a class="header-anchor" href="#vii-20-সক্রিয়করণ-কৌশল" aria-label="Permalink to &quot;VII. 20% সক্রিয়করণ কৌশল&quot;">​</a></h2><p>&quot;20% সক্রিয়করণ কৌশল&quot; হলো অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশন প্রতিষ্ঠার প্রাথমিক পর্যায়ের মূল কৌশলগুলোর মধ্যে একটি, এবং এর লক্ষ্য হলো সিভিলাইজেশন প্রতিষ্ঠার পরের প্রথম যুগে, সকল প্রাণীর মোট সংখ্যার 20% ব্যক্তিকে ফেস-স্তরের সর্বোচ্চ শক্তিশালীর স্তরে সক্রিয় করা।</p><h3 id="_7-1-কৌশলগত-লক্ষ্য" tabindex="-1">7.1 কৌশলগত লক্ষ্য <a class="header-anchor" href="#_7-1-কৌশলগত-লক্ষ্য" aria-label="Permalink to &quot;7.1 কৌশলগত লক্ষ্য&quot;">​</a></h3><ul><li>স্বল্পমেয়াদী লক্ষ্য (সিভিলাইজেশন প্রতিষ্ঠার পর 100 বছরের মধ্যে): 1% প্রাণীকে বেন-ইয়ান জিং এ সক্রিয় করা</li><li>মাঝারি মেয়াদী লক্ষ্য (সিভিলাইজেশন প্রতিষ্ঠার পর 500 বছরের মধ্যে): 10% প্রাণীকে বেন-ইয়ান জিং এ সক্রিয় করা</li><li>দীর্ঘমেয়াদী লক্ষ্য (সিভিলাইজেশন প্রতিষ্ঠার পর 1000 বছরের মধ্যে): 20% প্রাণীকে বেন-ইয়ান জিং এ সক্রিয় করা</li></ul><h3 id="_7-2-কৌশলগত-সহায়তা" tabindex="-1">7.2 কৌশলগত সহায়তা <a class="header-anchor" href="#_7-2-কৌশলগত-সহায়তা" aria-label="Permalink to &quot;7.2 কৌশলগত সহায়তা&quot;">​</a></h3><p>20% সক্রিয়করণ কৌশলের বাস্তবায়ন নিম্নলিখিত সহায়তা শর্তের উপর নির্ভর করে:</p><ul><li><strong>তিনশট সিস্টেম উন্মুক্ত</strong>: সকল প্রাণীর জন্য প্রচুর সাধনার পথের পছন্দ প্রদান করা</li><li><strong>দ্বিগুণ ফল প্রযুক্তি প্রচার</strong>: শতগুণ সাধনা ডিডাকশন বৃদ্ধি সাধনার দক্ষতাকে ব্যাপকভাবে বাড়ায়</li><li><strong>যৌথ উৎপাদন চুক্তি মেকানিজম</strong>: সাধকদের জন্য স্থির সম্পদ সহায়তা প্রদান করা</li><li><strong>সবার পথ রয়েছে ব্যবস্থা</strong>: প্রতিটি জীবনের মৌলিক সাধনার শর্ত নিশ্চিত করা</li><li><strong>শিক্ষক নেটওয়ার্ক</strong>: উচ্চ-স্তরের সাধক প্রাথমিক সাধকদের নির্দেশনা দেয়, এবং মানব সম্পদের প্রশিক্ষণ ত্বরান্বিত করে</li></ul><h3 id="_7-3-কৌশলগত-তাৎপর্য" tabindex="-1">7.3 কৌশলগত তাৎপর্য <a class="header-anchor" href="#_7-3-কৌশলগত-তাৎপর্য" aria-label="Permalink to &quot;7.3 কৌশলগত তাৎপর্য&quot;">​</a></h3><p>20% সক্রিয়করণ কৌশলের তাৎপর্য কেবল প্রচুর শক্তিশালী প্রশিক্ষণের মধ্যে সীমাবদ্ধ নয়, বরং আরও:</p><ul><li>মহাবিশ্বের সামগ্রিক উন্নয়নের জন্য পর্যাপ্ত শক্তির ভিত্তি প্রদান করা</li><li>বিশাল শক্তিশালীদের গোষ্ঠী প্রতিষ্ঠা করা, এবং পৃথক শক্তিশালীদের ক্ষমতার একচেটিয়া রোধ করা</li><li>&quot;শক্তিশালী বারবার আসে&quot; এমন সিভিলাইজেশনের পরিবেশ তৈরি করা, এবং আরও বেশি জীবনকে কঠোর পরিশ্রমে সাধনা করতে অনুপ্রাণিত করা</li><li>সকল জাতির প্রজাতন্ত্রের জন্য ব্যাপক শক্তিশালীদের ভিত্তি প্রদান করা, এবং প্রতিটি জাতির নিজস্ব সর্বোচ্চ শক্তিশালী প্রতিনিধি রয়েছে তা নিশ্চিত করা</li></ul><h2 id="viii-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-অধিকার-এবং-ব্যবস্থা" tabindex="-1">VIII. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের অধিকার এবং ব্যবস্থা <a class="header-anchor" href="#viii-ফেস-স্তরের-সর্বোচ্চ-শক্তিশালীদের-অধিকার-এবং-ব্যবস্থা" aria-label="Permalink to &quot;VIII. ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের অধিকার এবং ব্যবস্থা&quot;">​</a></h2><p>তাদের গ্রহণ করা দায়িত্বের প্রতিদান হিসেবে, ফেস-স্তরের সর্বোচ্চ শক্তিশালী নিম্নলিখিত অধিকার এবং ব্যবস্থা উপভোগ করে:</p><ul><li><strong>সম্পদ অগ্রাধিকার</strong>: সাধনা সম্পদের বন্টনে সর্বোচ্চ অগ্রাধিকার উপভোগ করা</li><li><strong>আইন অংশগ্রহণের অধিকার</strong>: মহাবিশ্বের আইনের সূক্ষ্ম সমন্বয় এবং অপ্টিমাইজেশনের সিদ্ধান্তে অংশ নেওয়ার অধিকার রয়েছে</li><li><strong>স্থান তৈরির অধিকার</strong>: নিজের স্বাধীন স্থান বা বিশ্ব তৈরি করার অধিকার রয়েছে</li><li><strong>সিভিলাইজেশন সিদ্ধান্তের অধিকার</strong>: সিভিলাইজেশনের সর্বোচ্চ সিদ্ধান্ত প্রতিষ্ঠানে আসন এবং ভোটের অধিকার রয়েছে</li><li><strong>ক্রস-ফেস যাত্রার অধিকার</strong>: সিম্বায়োটিক সিভিলাইজেশনের নিয়ন্ত্রণাধীন সব ফেসে স্বাধীন যাত্রার অধিকার রয়েছে</li><li><strong>সম্মান এবং শ্রদ্ধা</strong>: পুরো সিভিলাইজেশন থেকে সম্মান এবং শ্রদ্ধা পায়, এবং তার কীর্তি সিভিলাইজেশনের ইতিহাসে লিপিবদ্ধ হয়</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>ফেস-স্তরের সর্বোচ্চ শক্তিশালীদের মানদণ্ড হলো অ্যাঙ্কর সিম্বায়োটিক সিভিলাইজেশন দ্বারা &quot;শক্তিশালী&quot; এই ধারণার পুনরায় সংজ্ঞায়ন। সিম্বায়োটিক সিভিলাইজেশনে, শক্তিশালী লুটেরা নন, আধিপত্য নন, এবং উঁচু আসনে বসা শাসক নন, বরং তারা রক্ষক, সেবাকারী, এবং পথপ্রদর্শক। শক্তির মাত্রা হলো ভিত্তি, চরিত্রের মাত্রা হলো আত্মা, অবদানের মাত্রা হলো মূল্য, এবং দায়িত্বের মাত্রা হলো দায়িত্ববোধ — চারটি মাত্রা একত্রিত হলেই প্রকৃত &quot;ফেস-স্তরের সর্বোচ্চ শক্তিশালী&quot; হয়। 20% সক্রিয়করণ কৌশলের লক্ষ্য, কেবল 20% শক্তিশালী প্রশিক্ষণ করা নয়, বরং 20% এমন রক্ষক প্রশিক্ষণ করা যারা সকল জাতির সিম্বায়োসিস এবং মহাবিশ্বের উন্নয়নের জন্য দায়িত্ব গ্রহণ করতে ইচ্ছুক। যখন 20% প্রাণী ফেস-স্তরের সর্বোচ্চ শক্তিশালীর স্তরে পৌঁছায় এবং সিম্বায়োসিস ধারণা অনুশীলন করে, তখন মহাবিশ্বের সামগ্রিক উন্নয়ন আর দূরের স্বপ্ন থাকবে না।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (সাধনা স্তরের ঐক্যকৃত বিভাজন)</li><li>23-20%激活战略规划 (20% সক্রিয়করণ কৌশল পরিকল্পনা)</li><li>19-修炼伦理与边界 (সাধনার নৈতিকতা এবং সীমা)</li></ul>',61)])])}const c=a(r,[["render",e]]);export{b as __pageData,c as default};
